let db={reports:[],draft:null,large:false,motionPaused:false},storageAvailable=true,view='home',currentReport=null,index=0,answers=Array(QUESTION_COUNT).fill(null),hasUnsavedAnswers=false,selectedCategory=0,selectedLifeContext='daily',evidenceFilter=null,pairAxes=[0,2],discoveryIntent='self',homeDemoView='map';
