function bindActions(){app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action;if(action==='start')start(false);if(action==='resume')start(true);if(action==='home')home();if(action==='full')openFullReport();if(action==='print')window.print();if(action==='share')shareReport();if(action==='history')history();if(action==='email')saveReportScreen(currentReport);if(action==='new')confirmStartOver();});app.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{const r=db.reports.find(r=>r.id===b.dataset.report);if(r){if(r.version===VERSION&&!r.fullViewed)reportPreview(r);else result(r)}});}
function home(focus=true){setView('home');discoveryIntent=validIntent(db.draft?.intent);app.innerHTML=discoveryHomeMarkup({language:locale,draft:db.draft,reportLanguageNote:reportNote(assessmentLanguage),reportLanguageDir:languages.find(item=>item.code===assessmentLanguage)?.dir||'ltr',demoView:homeDemoView});bindActions();for(const button of app.querySelectorAll('[data-start-intent]'))button.onclick=()=>{discoveryIntent=validIntent(button.dataset.startIntent);if(db.draft)db.draft.intent=discoveryIntent;start(!!db.draft)};for(const button of app.querySelectorAll('[data-home-view]'))button.onclick=()=>{homeDemoView=button.dataset.homeView;for(const other of app.querySelectorAll('[data-home-view]'))other.setAttribute('aria-pressed',String(other===button));$('#home-demo-content').innerHTML=homeDemoMarkup(homeDemoView,locale)};$('#explore-preview').onclick=()=>{const preview=$('#home-report-preview');preview.tabIndex=-1;preview.focus({preventScroll:true});preview.scrollIntoView({block:'center',behavior:scrollBehavior()})};if(focus)focusTitle()}

function confirmStartOver(){if(!db.draft){start(false);return}showDialog('Start a fresh assessment?',`<p>This will replace the ${db.draft.answers.filter(a=>a!==null).length} answers in your unfinished assessment. Your completed reports will stay saved.</p><div class="dialog-actions"><button class="secondary" data-dialog-close>Keep my place</button><button class="primary" id="restart-confirm">Start again</button></div>`);$('#restart-confirm').onclick=()=>{$('#info').close();start(false)}}
function start(resume){headingSpace=0;headingSpaceKey='';thumbRowY=null;if(resume&&validDraft(db.draft)){answers=[...db.draft.answers];index=db.draft.index;discoveryIntent=validIntent(db.draft.intent);persistDraft()}else{answers=Array(QUESTION_COUNT).fill(null);index=0;db.draft={version:VERSION,answers:[...answers],index,intent:discoveryIntent};save()}quiz()}
function persistDraft(){db.draft={version:VERSION,answers:[...answers],index,intent:discoveryIntent};return save()}
let guidedScrollTimer=null,guidedScrollKind=null,thumbRowY=null,headingSpace=0,headingSpaceKey='';
function cancelGuidedScroll(){clearTimeout(guidedScrollTimer);guidedScrollTimer=null;guidedScrollKind=null}
function scrollBehavior(){return gentleMotionPreference.matches||db.motionPaused?'instant':'smooth'}
function measureMobileQuestionSpace(){const shell=app.querySelector('.batch-quiz');if(!shell)return;shell.style.removeProperty('--question-heading-space');if(!window.matchMedia('(max-width:700px)').matches){headingSpace=0;return}const key=[locale,innerWidth,db.large].join(':');if(key!==headingSpaceKey){headingSpace=0;headingSpaceKey=key;thumbRowY=null;shell.style.removeProperty('--thumb-runway')}const heights=[...app.querySelectorAll('.batch-question h2')].map(title=>title.getBoundingClientRect().height);headingSpace=Math.max(headingSpace,...heights,0);shell.style.setProperty('--question-heading-space',`${Math.ceil(headingSpace)}px`)}
function revealQuestion(target){const headerHeight=$('.quiz-statusbar')?.getBoundingClientRect().height||0;if(window.matchMedia('(max-width:700px)').matches&&thumbRowY!==null){const row=target.closest('.batch-question')?.querySelector('.batch-options'),rect=row?.getBoundingClientRect();if(rect){const position=thumbScrollTarget({scrollY:window.scrollY,rowTop:rect.top,rowHeight:rect.height,headingTop:target.getBoundingClientRect().top,headerHeight,viewportHeight:innerHeight,anchorY:thumbRowY});if(position){thumbRowY=position.anchor;app.querySelector('.batch-quiz').style.setProperty('--thumb-runway',`${position.runway}px`);window.scrollTo({top:position.top,behavior:scrollBehavior()});return}}}window.scrollTo({top:Math.max(0,window.scrollY+target.getBoundingClientRect().top-headerHeight-24),behavior:scrollBehavior()})}
window.addEventListener('resize',()=>{if(view==='quiz'){thumbRowY=null;measureMobileQuestionSpace()}});
document.fonts?.ready.then(()=>{if(view==='quiz')measureMobileQuestionSpace()});
function scheduleGuidedScroll(from){cancelGuidedScroll();const sourcePage=questionPage(from).start,isComplete=pageStatus(answers,from).complete;guidedScrollKind=isComplete?'page':'question';guidedScrollTimer=setTimeout(()=>{guidedScrollTimer=null;guidedScrollKind=null;if(view!=='quiz'||questionPage(index).start!==sourcePage||(!isComplete&&index!==from)||$('#info').open)return;const destination=nextGuidedQuestion(answers,from);if(destination===null){const button=questionPage(from).next===null?$('#next'):$('#ready-results');button.focus({preventScroll:true});button.scrollIntoView({block:'center',behavior:scrollBehavior()});return}const samePage=sourcePage===questionPage(destination).start;index=destination;persistDraft();if(!samePage){quiz({guided:true});return}const target=$(`#question-title-${destination}`);target.focus({preventScroll:true});revealQuestion(target)},isComplete?220:450)}
// Ordinary pointer/scroll/Tab activity must not lose a just-completed page transition.
// Explicit navigation and further answer edits still cancel the pending move.
function cancelQuestionScroll(){if(guidedScrollKind!=='page')cancelGuidedScroll()}
for(const eventName of ['wheel','touchstart','pointerdown'])document.addEventListener(eventName,cancelQuestionScroll,{passive:true});
document.addEventListener('keydown',event=>{if(event.key==='Escape')cancelGuidedScroll();else if(['Tab','PageUp','PageDown','Home','End','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))cancelQuestionScroll()});
let batchRenderKey='';
function batchQuestionMarkup(questionIndex){const question=questions[questionIndex],value=answers[questionIndex];return `<section class="batch-question" data-question-index="${questionIndex}" id="question-${questionIndex}"><h2 tabindex="-1" id="question-title-${questionIndex}"><span class="batch-question-number">${questionIndex+1}.</span> ${escape(question.text)}</h2><fieldset class="batch-scale" aria-labelledby="question-title-${questionIndex}"><legend class="sr-only">${escape(question.text)}</legend><div class="batch-scale-labels" aria-hidden="true"><span>${escape(agreement[0])}</span><span>${escape(batchCopy(locale).neutral)}</span><span>${escape(agreement[4])}</span></div><div class="batch-options">${agreement.map((label,choice)=>`<label class="batch-option" data-choice="${choice}" title="${escape(label)}"><input type="radio" name="response-${questionIndex}" value="${choice}" aria-label="${escape(label)}" ${value===choice?'checked':''}><span aria-hidden="true">✓</span></label>`).join('')}</div></fieldset><p class="batch-response" id="response-${questionIndex}"><span data-response-value>${value===null?'&nbsp;':'✓ '+escape(agreement[value])}</span>${agreement.map(label=>`<span class="batch-response-measure" aria-hidden="true">✓ ${escape(label)}</span>`).join('')}</p></section>`}
function quiz({guided=false}={}){if(!guided)thumbRowY=null;
 const reuse=view==='quiz'&&!!app.querySelector('.quiz-shell');setView('quiz');const page=questionPage(index);
 if(!reuse){batchRenderKey='';app.innerHTML=`<div class="quiz-shell batch-quiz"><div class="quiz-statusbar"><div class="quiz-toolbar"><h1 id="question-title" tabindex="-1"><span>Questions</span> <strong id="question-number"></strong><small> of 36</small></h1><button class="text-button" id="pause">Save & take a break</button></div><div class="progress-track" role="progressbar" aria-label="Assessment completed" aria-valuemin="0" aria-valuemax="36"><div></div></div><progress id="sticky-progress" max="36" value="0" aria-label="Assessment completed"></progress><div class="quiz-shortcuts"><span id="page-answered" role="status" aria-live="polite"></span><button class="text-button" id="question-picker">Questions <span id="answered-count"></span> ▾</button><button class="primary" id="ready-results" hidden>Go to results →</button></div></div>${companionMarkup()}<p class="batch-help" id="answer-help"></p><div id="batch-questions"></div><div class="batch-footer"><div class="batch-page-status"><span id="page-position"></span><button class="text-button" id="jump-last">Last question →</button></div><div class="quiz-actions"><button class="secondary" id="previous"><span aria-hidden="true">←</span> Previous</button><button class="primary" id="next"><span id="next-label"></span><span aria-hidden="true">→</span></button></div></div><p class="save-status" id="save-status"></p></div>`;
 mountJourney();$('#motion-toggle').onclick=()=>{db.motionPaused=!db.motionPaused;save();updateCompanion()};$('#question-picker').onclick=openQuestionPicker;$('#jump-last').onclick=()=>jumpToQuestion(QUESTION_COUNT-1);$('#ready-results').onclick=finish;$('#previous').onclick=()=>moveQuestion(-1);$('#next').onclick=()=>{const current=questionPage(index);if(assessmentStatus(answers).complete||current.next===null)finish();else jumpToQuestion(current.next)};
 $('#pause').onclick=()=>{if(persistDraft()){home();toast('Your place is saved. Come back whenever you are ready.')}else showDialog('Keep this tab open',`<p>This browser could not save your progress. Your answers are still here, but closing or refreshing the tab may lose them.</p><button class="primary" data-dialog-close>Continue assessment</button>`)};
 }
 $('#question-number').textContent=page.start===page.end-1?String(page.start+1):`${page.start+1}–${page.end}`;
 $('#answer-help').textContent=batchCopy(locale).help;
 const renderKey=[page.start,locale].join(':');
 if(batchRenderKey!==renderKey){$('#batch-questions').innerHTML=page.indices.map(batchQuestionMarkup).join('');batchRenderKey=renderKey;
 for(const card of app.querySelectorAll('.batch-question')){card.addEventListener('focusin',()=>{const destination=Number(card.dataset.questionIndex);if(index!==destination){index=destination;persistDraft()}updateQuestionFocus()})}
 for(const input of app.querySelectorAll('.batch-option input')){
  const questionIndex=Number(input.closest('[data-question-index]').dataset.questionIndex);
  input.addEventListener('change',()=>{selectAnswer(Number(input.value),questionIndex)});
  input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();selectAnswer(Number(input.value),questionIndex)}});
 }

 }
 measureMobileQuestionSpace();$('#previous').disabled=page.previous===null;$('#next-label').textContent=page.next===null?t('See results'):`${t('Next')} ${questionPage(page.next).indices.length}`;
 updateBatchProgress();
 const target=$(`#question-title-${index}`)||$('#question-title');target.focus({preventScroll:true});
 if(guided)revealQuestion(target);else if(index===page.start)window.scrollTo({top:0,behavior:'instant'});else target.scrollIntoView({block:'center',behavior:'instant'});
}
function updateQuestionFocus(){for(const card of app.querySelectorAll('.batch-question')){const i=Number(card.dataset.questionIndex),current=i===index;card.classList.toggle('is-current',current);card.classList.toggle('is-answered',Number.isInteger(answers[i]));if(current)card.setAttribute('aria-current','step');else card.removeAttribute('aria-current')}}
function updateBatchProgress(){updateQuestionFocus();const all=assessmentStatus(answers),page=pageStatus(answers,index);$('#next').classList.toggle('results-ready',all.complete||page.next===null);$('#next-label').textContent=all.complete||page.next===null?t('See results'):`${t('Next')} ${questionPage(page.next).indices.length}`;$('.progress-track').setAttribute('aria-valuenow',all.answered);$('#sticky-progress').value=all.answered;$('.progress-track>div').style.width=`${all.answered/QUESTION_COUNT*100}%`;$('#page-position').innerHTML=`${escape(batchCopy(locale).page)} <bdi dir="ltr">${page.number} / ${page.total}</bdi>`;$('#page-answered').innerHTML=`<bdi dir="ltr">✓ ${all.answered} / ${QUESTION_COUNT}</bdi>`;const status=$('#save-status');status.classList.toggle('sr-only',storageAvailable);status.textContent=storageAvailable?'Progress saved.':'Browser storage is unavailable. Keep this tab open to keep your answers.';updateQuizShortcuts()}
function jumpToQuestion(destination){cancelGuidedScroll();if(!Number.isInteger(destination)||destination<0||destination>=questions.length)return;index=destination;persistDraft();quiz()}
function moveQuestion(direction){const page=questionPage(index),destination=direction<0?page.previous:page.next;if(destination!==null)jumpToQuestion(destination)}
function updateQuizShortcuts(){const status=assessmentStatus(answers);$('#answered-count').textContent=`(${status.answered}/36)`;$('#ready-results').hidden=!status.complete;$('#jump-last').hidden=status.complete;$('#jump-last').disabled=index===questions.length-1;updateCompanion();}
const gentleMotionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
function mountJourney(){const companion=$('#growth-companion'),art=$('#growth-art');companion.classList.add('has-journey');companion.querySelector('.companion-copy p:last-child').id='journey-caption';companion.querySelector('.companion-heading').id='journey-heading';companion.insertAdjacentHTML('beforeend',journeyTrailMarkup());$('#journey-traveler').append(art);companion.querySelectorAll('[data-journey-stop]').forEach(button=>button.onclick=()=>{const state=journeyState(answers),stop=state.stops[Number(button.dataset.journeyStop)];if(!stop?.available)return;if(stop.index===4&&assessmentStatus(answers).complete)finish();else jumpToQuestion(stop.question)})}
function updateJourney(){const companion=$('#growth-companion');if(!companion?.classList.contains('has-journey'))return;const state=journeyState(answers);companion.style.setProperty('--journey-progress',String(state.progress));companion.style.setProperty('--journey-x',`${state.x}%`);companion.style.setProperty('--journey-y',`${state.y}px`);$('#journey-heading').textContent=`Your journey · ${state.stops[state.activeIndex].name}`;$('#journey-caption').textContent=state.stops[state.activeIndex].caption;companion.querySelectorAll('[data-journey-stop]').forEach(button=>{const stop=state.stops[Number(button.dataset.journeyStop)];button.disabled=!stop.available;button.classList.toggle('current',stop.current);button.classList.toggle('passed',stop.passed);button.setAttribute('aria-label',`${stop.name}, ${stop.current?'current chapter':stop.available?'revisit this chapter':'ahead on your journey'}`);if(stop.current)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');button.title=stop.available?(stop.index===4?'Open your results':`Go to question ${stop.question+1}`):`Opens after ${stop.threshold} answers`;button.querySelector('.journey-pin').textContent=stop.passed?'✓':String(stop.index+1)})}
function updateCompanion(){const companion=$('#growth-companion');if(!companion)return;const state=growthState(answers),paused=db.motionPaused===true||gentleMotionPreference.matches;companion.dataset.growthStage=state.stage;companion.style.setProperty('--stem-reveal',String(state.stem));companion.classList.toggle('motion-paused',paused);app.querySelector('.batch-quiz')?.classList.toggle('selection-motion-paused',paused);$('#growth-art').setAttribute('aria-label',`Progress plant: ${state.name}. ${state.answered} of 36 questions answered.`);const button=$('#motion-toggle');button.disabled=gentleMotionPreference.matches;button.setAttribute('aria-pressed',String(paused));const label=gentleMotionPreference.matches?'Motion paused for your reduced-motion preference':paused?'Resume gentle motion':'Pause gentle motion';button.setAttribute('aria-label',label);button.title=label;button.textContent=paused?'▶':'Ⅱ';updateJourney()}
gentleMotionPreference.addEventListener('change',()=>{if(view==='quiz')updateCompanion()});
function openQuestionPicker(){const status=assessmentStatus(answers);showDialog('Jump to a question',`<p>${status.answered} of 36 answered. Your answers stay saved.</p><p class="question-key">✓ Answered &nbsp; · &nbsp; Unmarked questions still need an answer.</p><div class="question-grid">${questions.map((_,i)=>{const answered=Number.isInteger(answers[i])&&answers[i]>=0&&answers[i]<=4;return `<button class="question-number ${answered?'answered':''} ${i===index?'current':''}" data-jump-question="${i}" aria-label="Question ${i+1}, ${answered?'answered':'unanswered'}${i===index?', current question':''}" ${i===index?'aria-current="step"':''}>${i+1}${answered?'<span aria-hidden="true">✓</span>':''}</button>`}).join('')}</div>${status.complete?'<button class="primary picker-results" id="picker-results">Go to results →</button>':''}`);$('#info').querySelectorAll('[data-jump-question]').forEach(button=>button.onclick=()=>{$('#info').close();jumpToQuestion(Number(button.dataset.jumpQuestion))});const results=$('#picker-results');if(results)results.onclick=()=>{$('#info').close();finish()}}
function selectAnswer(value,questionIndex=index){if(view!=='quiz'||!Number.isInteger(value)||value<0||value>4||!questionPage(index).indices.includes(questionIndex))return;const firstAnswer=answers[questionIndex]===null;cancelGuidedScroll();index=questionIndex;answers[index]=value;persistDraft();const input=app.querySelector(`input[name="response-${index}"][value="${value}"]`);if(input)input.checked=true;if(firstAnswer&&input&&window.matchMedia('(max-width:700px)').matches){const rect=input.closest('.batch-options').getBoundingClientRect();thumbRowY=Math.min(innerHeight-80,rect.top+rect.height/2);app.querySelector('.batch-quiz').style.setProperty('--thumb-runway',`${Math.max(0,innerHeight-thumbRowY)}px`)}const response=$(`#response-${index} [data-response-value]`);if(response)response.textContent='✓ '+agreement[value];updateBatchProgress();if(firstAnswer)scheduleGuidedScroll(questionIndex)}

function finish(){const unanswered=answers.map((answer,i)=>answer===null?i:-1).filter(i=>i>=0);if(unanswered.length){showDialog('A few answers are still missing.',`<p>${unanswered.length} of 36 questions ${unanswered.length===1?'still needs':'still need'} an answer before we can create your report.</p><div class="dialog-actions"><button class="primary" id="answer-remaining">Answer remaining questions →</button><button class="secondary" data-dialog-close>Keep reviewing</button></div>`);$('#answer-remaining').onclick=()=>{$('#info').close();index=unanswered[0];persistDraft();quiz()};return}prepareReport()}
const nextFrame=()=>new Promise(resolve=>requestAnimationFrame(resolve));
async function prepareReport(){
 setView('preparing');app.innerHTML=preparationMarkup();focusTitle();
 // Yield for the preparation screen to paint; each step reflects actual work, with no countdown.
 await nextFrame();await nextFrame();if(view!=='preparing')return;
 try{const scores=scoreAnswers(answers);$('#prepare-scores').classList.add('complete');
 await nextFrame();if(view!=='preparing')return;
 leanGroups(scores);scores.forEach((_,i)=>categoryInsight(scores,i));$('#prepare-graphs').classList.add('complete');
 const r={version:VERSION,id:crypto.randomUUID(),date:new Date().toISOString(),scores,intent:discoveryIntent,responses:[...answers],context:contextAnswers(answers),questionLanguage:assessmentLanguage,fullViewed:false,steps:{}};
 db.reports.unshift(r);db.draft=null;currentReport=r;const saved=save();$('#prepare-save').classList.toggle('complete',saved);
 $('#prepare-status').textContent=t(saved?'Your report is ready.':'Report ready. Browser storage is unavailable; save a PDF before leaving.');
 const button=$('#preparation-continue');button.disabled=false;button.onclick=()=>reportPreview(r);
 }catch(error){toast(error.message);quiz()}
}
function reportPreview(r){if(!r||r.version!==VERSION)return;setView('report-preview');currentReport=r;app.innerHTML=reportPreviewMarkup({profile:profileFor(r.scores),scores:r.scores,traits,language:locale});$('#preview-skip').onclick=()=>result(r);$('#preview-full').onclick=()=>{result(r);openFullReport()};$('#preview-download').onclick=()=>{r.fullViewed=true;save();result(r);window.print()};focusTitle()}
function saveReportScreen(r){if(!r)return;setView('save-report');currentReport=r;app.innerHTML=`<section class="save-report flow-page"><div class="save-flower" aria-hidden="true">✳</div><h1>Keep your discovery close.</h1><p>Your report is saved in this browser. You can also open an email draft with your summary.</p><form id="email-summary"><label for="report-email">Your email address</label><input type="email" id="report-email" name="email" autocomplete="email" placeholder="you@example.com" required><button class="primary" type="submit">Open email draft →</button><p class="support-note">This opens your email app. Review and send the message there. Innerly does not send or collect your email.</p></form><p id="email-status" role="status"></p><button class="text-button" id="skip-save">Skip for now →</button></section>`;
 $('#skip-save').onclick=()=>result(r);$('#email-summary').onsubmit=e=>{e.preventDefault();const email=$('#report-email').value.trim();if(!$('#email-summary').reportValidity())return;const href=emailDraft({email,profile:profileFor(r.scores),scores:r.scores,traits,language:locale,url:location.origin+location.pathname});const link=document.createElement('a');link.href=href;link.click();$('#email-status').textContent=t('Return here to view your report.');$('#skip-save').textContent=t('View my report →')};focusTitle();
 if(!storageAvailable)app.querySelector('.save-report>p').textContent=t('Browser storage is unavailable. Keep this tab open to keep your answers.');
}
const dateLabel=date=>new Date(date).toLocaleDateString(locale,{day:'numeric',month:'long',year:'numeric'});
function graphMarkup(scores,dimensions=traits){return `<div class="trait-graphs">${dimensions.map((t,i)=>`<div class="trait-graph"><div class="trait-label"><h3>${t.name}</h3><strong>${scores[i]}<span> / 100</span></strong></div><div class="spectrum" style="--trait-color:${t.color};--position:${scores[i]}%" role="img" aria-label="${t.name}: ${scores[i]} out of 100. Lower scores lean toward ${t.low.toLowerCase()}, higher scores toward ${t.high.toLowerCase()}."><div class="spectrum-fill"></div><span class="spectrum-mid" aria-hidden="true"></span><span class="spectrum-dot" aria-hidden="true"></span></div><div class="spectrum-labels"><span>${t.low}</span><span>${t.high}</span></div></div>`).join('')}</div>`}
function result(r,focus=true){if(r.version===ARCHIVED_VERSION){archivedReport(r);return}setView('result');currentReport=r;selectedCategory=intentDimensions(r.intent)[0];if(focus)selectedLifeContext=intentContext(r.intent);if(!Array.isArray(r.categoryPlan)&&r.steps){const mapping=[0,2,3];r.categoryPlan=mapping.filter((_,i)=>r.steps[i]===true);r.categoryDone=Object.fromEntries(r.categoryPlan.map(i=>[i,true]));save()}const profile=profileFor(r.scores),expanded=r.fullViewed===true;app.innerHTML=`<p class="language-note report-language-note" lang="${assessmentLanguage}" dir="${languages.find(item=>item.code===assessmentLanguage)?.dir||'ltr'}">${reportNote(assessmentLanguage)}</p><section class="report-heading"><h1>Your personality</h1><p>${dateLabel(r.date)} · Based on your 36 answers</p></section><section class="summary-card"><div><h2>${profile.title}</h2><p>${profile.summary}</p></div></section><section class="report-panel"><div class="section-heading"><h2>Your five dimensions</h2></div>${graphMarkup(r.scores)}<p class="graph-note">Preferences, not grades. Neither end is better.</p></section><section class="full-report-invite ${expanded?'expanded-invite':''}"><div><h2>Want to understand more?</h2><div class="free-label">Full report · Free for now</div><ul class="report-value-list"><li>Five dimensions, explained simply</li><li>Interactive maps and charts</li><li>Small steps for everyday life</li></ul><p class="support-note">No payment needed. Your full report is free for now.</p></div><button class="primary" data-action="full" aria-expanded="${expanded}" aria-controls="full-report">${expanded?'Go to full report':'View full report'} <span aria-hidden="true">→</span></button></section><section id="full-report" ${expanded?'':'hidden'}>${expanded?fullReportMarkup(r):''}</section>${contextMarkup(r)}<section class="report-panel today-preview"><h2>A small step for today</h2><p>${categoryInsight(r.scores,0).step}</p></section><div class="report-actions"><button class="secondary" data-action="email">Save or email summary</button><button class="secondary" data-action="share">Download summary card</button><button class="secondary" data-action="history">My saved reports</button><button class="text-button" data-action="home">Back to home</button></div><p class="honest-note">For self-reflection. This questionnaire has not been clinically validated.</p>`;bindActions();bindReport();if(focus)focusTitle()}
function profileMapMarkup(r){
 const cx=180,cy=163,radius=101;
 const point=(i,f)=>[cx+Math.cos(-Math.PI/2+i*Math.PI*2/5)*radius*f,cy+Math.sin(-Math.PI/2+i*Math.PI*2/5)*radius*f];
 const polygon=f=>traits.map((_,i)=>point(i,f).join(',')).join(' ');
 return `<svg class="interactive-radar" viewBox="0 0 360 325" role="group" aria-label="Interactive personality map. Select a category point to explore it.">${[.25,.5,.75,1].map(f=>`<polygon points="${polygon(f)}" fill="none" stroke="#d4decb"/>`).join('')}${traits.map((_,i)=>`<line x1="${cx}" y1="${cy}" x2="${point(i,1)[0]}" y2="${point(i,1)[1]}" stroke="#d4decb"/>`).join('')}<polygon points="${r.scores.map((score,i)=>point(i,score/100).join(',')).join(' ')}" fill="#8ca87344" stroke="#6a8855" stroke-width="2"/>${traits.map((t,i)=>{const p=point(i,r.scores[i]/100),label=point(i,1.28);return `<g class="radar-axis ${i===selectedCategory?'active':''}" data-radar-axis="${i}"><line x1="${cx}" y1="${cy}" x2="${point(i,1)[0]}" y2="${point(i,1)[1]}" stroke="${t.color}" class="axis-highlight"/><a href="#category-details" data-category="${i}" aria-label="Explore ${t.name}, ${r.scores[i]} out of 100"><circle cx="${p[0]}" cy="${p[1]}" r="22" fill="transparent"/><circle cx="${p[0]}" cy="${p[1]}" r="5.5" fill="${t.color}" stroke="white" stroke-width="2"/></a><text data-category="${i}" aria-hidden="true" x="${label[0]}" y="${label[1]}" text-anchor="middle" dominant-baseline="middle" fill="#40523a" font-size="16" font-family="Arial, sans-serif">${t.short}</text></g>`}).join('')}</svg>`;
}
function categoryDetailMarkup(r){return personalDetailMarkup(r,selectedCategory,{language:locale,context:selectedLifeContext,added:selectedActions(r).some(a=>a.index===selectedCategory)})}
function planMarkup(r){const actions=selectedActions(r),progress=planProgress(r);return `<div class="plan-progress-row"><div class="plan-donut" style="--plan-percent:${progress.percent}%" role="img" aria-label="${progress.done} of ${progress.total} selected activities tried"><span><strong>${progress.done}<small> / ${progress.total}</small></strong><span>steps tried</span></span></div><div><h3>Small steps, your way.</h3><p>${progress.total?'Try an activity, then tick it here. No streaks or deadlines.':'Choose a category above and add one small activity to begin.'}</p><p class="support-note">This chart tracks activities you mark as tried, not personality improvement.</p></div></div><div class="category-action-list">${actions.map(action=>`<div class="saved-category-action"><label><input type="checkbox" data-category-done="${action.index}" ${action.done?'checked':''}><span><strong>${action.trait.name}</strong><span>${action.step}</span></span></label><button class="remove-action" data-remove-category="${action.index}" aria-label="Remove ${action.trait.name.toLowerCase()} activity from my plan">Remove</button></div>`).join('')}</div><div class="plan-live sr-only" role="status">${progress.done} of ${progress.total} steps tried.</div>`}
function barChartMarkup(r){return preferencePathsMarkup(r,selectedCategory,locale)}
function pieChartMarkup(r){return connectionsMarkup(r,pairAxes,locale,selectedCategory)}
function lineChartMarkup(r){return journeyMarkup(r,historySeries(db.reports,r,selectedCategory),selectedCategory,locale,dateLabel)}
function categoryPickerMarkup(r){return `<div class="explorer-categories" role="group" aria-label="Choose a personality category">${traits.map((trait,i)=>`<button class="explorer-category ${i===selectedCategory?'active':''}" data-category="${i}" aria-pressed="${i===selectedCategory}" style="--category-color:${trait.color}"><span class="category-picker-name">${trait.name}</span><strong>${r.scores[i]}<small> / 100</small></strong><span class="category-picker-track" aria-hidden="true"><span style="width:${r.scores[i]}%"></span></span></button>`).join('')}</div>`}
function selectedScoreMarkup(r){const insight=categoryInsight(r.scores,selectedCategory);return `<span class="selected-dimension-name">${insight.trait.name}</span><strong>${insight.score}<small> / 100</small></strong><span class="selected-dimension-meaning">${insight.title}</span>`}
function scoreTableMarkup(r){return `<details class="score-table"><summary>See all scores as a table</summary><table><thead><tr><th>Category</th><th>Score</th><th>Your preference</th></tr></thead><tbody>${traits.map((trait,i)=>`<tr><th scope="row">${trait.name}</th><td>${r.scores[i]} / 100</td><td>${categoryInsight(r.scores,i).title}</td></tr>`).join('')}</tbody></table></details>`}
function thinkingNavigationMarkup(){return `<div class="chart-tabs thinking-navigation" role="tablist" aria-label="${locale==='hi'?'खुद को समझने का एक नज़रिया चुनें':'Choose a way to explore yourself'}">${thinkingViews(locale).map(({key,title,prompt,icon},i)=>`<button role="tab" id="tab-${key}" data-chart-tab="${key}" aria-selected="${i===0}" aria-controls="panel-${key}" tabindex="${i===0?'0':'-1'}" data-no-translate><span class="thinking-icon" aria-hidden="true">${icon}</span><strong>${title}</strong><small>${prompt}</small></button>`).join('')}</div>`}
function chartGalleryMarkup(r){return `<section class="report-panel chart-gallery" aria-label="${locale==='hi'?'अपनी पसंद को समझें':'Explore your patterns'}"><div class="selected-dimension" id="chart-selection" role="status" aria-live="polite" style="--category-color:${traits[selectedCategory].color}">${selectedScoreMarkup(r)}</div><section id="panel-map" role="tabpanel" aria-labelledby="tab-map"><p class="support-note">Tap a point to explore a different dimension.</p>${profileMapMarkup(r)}<p class="graph-note">A larger shape is not a better personality.</p>${scoreTableMarkup(r)}</section><section id="panel-bar" role="tabpanel" aria-labelledby="tab-bar" hidden><div id="bar-chart-content">${barChartMarkup(r)}</div></section><section id="panel-pie" role="tabpanel" aria-labelledby="tab-pie" hidden><div id="pie-chart-content">${pieChartMarkup(r)}</div></section><section id="panel-line" role="tabpanel" aria-labelledby="tab-line" hidden><div id="line-chart-content">${lineChartMarkup(r)}</div></section><div id="graph-reading">${chartReadingMarkup('map',r,selectedCategory,[],locale)}</div><button class="text-button" id="read-dimension-story">${locale==='hi'?'इस आयाम की कहानी पढ़ें ↓':'Read this dimension’s story ↓'}</button></section>`}
function fullReportMarkup(r){return `<div class="full-report-heading"><div class="eyebrow">YOUR PERSONALITY EXPLORER</div><h2 tabindex="-1" id="full-report-title">A clearer picture of you.</h2><p data-no-translate>${locale==='hi'?'एक नज़रिया चुनें। अपनी पसंद पहचानें। अपना अगला कदम खोजें।':'Choose a view. Notice your patterns. Find your next step.'}</p></div>${intentReportMarkup(r,locale)}${overviewMarkup(r,locale)}${categoryPickerMarkup(r)}${thinkingNavigationMarkup()}<div class="explorer-dashboard">${chartGalleryMarkup(r)}<section class="report-panel category-explorer" aria-label="Your category insight"><div id="category-details" tabindex="-1">${categoryDetailMarkup(r)}</div></section></div><div id="answer-evidence">${evidenceMarkup(r,selectedCategory,{language:locale,filter:evidenceFilter})}</div><section class="report-panel category-plan" aria-labelledby="plan-title"><h2 id="plan-title">My simple action plan</h2><div id="category-plan-content">${planMarkup(r)}</div></section><details class="report-panel all-category-details"><summary>See all five categories together</summary><div class="all-category-content">${traits.map((t,i)=>{const item=categoryInsight(r.scores,i);return `<article><h3>${t.name} · ${r.scores[i]} / 100</h3><p>${item.meaning}</p><h4>Try today</h4><p>${item.step}</p>${allScenarioMarkup(r.scores,i,locale)}</article>`}).join('')}</div></details><details class="report-panel methodology"><summary>How your scores work</summary><p>Each category averages its own scored items: social style 7, information style 6, planning style 8, decision priorities 7, and decision pace 5. The five response positions (1–5) are scored internally from 0–4, with reverse-worded items reversed. The average is divided by 4 and shown from 0 to 100.</p><p>The final three items are separate reflections about calmness, noticing emotions, and making room for your own feelings. They do not contribute to the five scores.</p><p>Below 40 leans left, 40–60 suggests a mix, and above 60 leans right. These are illustrative bands, not validated cutoffs. Scores are preferences, not grades or population percentiles.</p><p>This questionnaire and its translations have not been clinically validated.</p></details><div class="print-action"><button class="primary" data-action="print">Save full report as PDF ↓</button><p class="support-note">Choose “Save as PDF” in your browser’s print window.</p></div>`}

function openFullReport(){if(!currentReport)return;const container=$('#full-report');if(!currentReport.fullViewed){currentReport.fullViewed=true;save();container.innerHTML=fullReportMarkup(currentReport);container.hidden=false;const button=app.querySelector('[data-action="full"]');button.setAttribute('aria-expanded','true');button.textContent='Go to full report →';bindReport();container.querySelector('[data-action="print"]').onclick=()=>window.print()}$('#full-report-title').focus({preventScroll:true});container.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function bindReport(){if(!currentReport||!$('#full-report')||$('#full-report').hidden)return;
 app.querySelectorAll('[data-category]').forEach(button=>button.onclick=e=>{e.preventDefault();chooseCategory(Number(button.dataset.category))});
 bindCategoryAction();bindCategoryPlan();bindChartGallery();bindPersonalInsights();bindEvidence();const storyButton=$('#read-dimension-story');if(storyButton)storyButton.onclick=()=>{$('#category-details').focus({preventScroll:true});$('#category-details').scrollIntoView({block:'start',behavior:scrollBehavior()})};
}
function chooseCategory(index){if(!Number.isInteger(index)||index<0||index>=traits.length)return;selectedCategory=index;evidenceFilter=null;
 app.querySelectorAll('[data-category]').forEach(button=>{const active=Number(button.dataset.category)===index;button.classList.toggle('active',active);if(button.tagName.toLowerCase()==='button')button.setAttribute('aria-pressed',String(active))});
 app.querySelectorAll('[data-radar-axis]').forEach(axis=>axis.classList.toggle('active',Number(axis.dataset.radarAxis)===index));
 $('#category-details').innerHTML=categoryDetailMarkup(currentReport);$('#chart-selection').innerHTML=selectedScoreMarkup(currentReport);$('#chart-selection').style.setProperty('--category-color',traits[index].color);bindCategoryAction();bindPersonalInsights();syncGalleryCategory();updateChartReading();if($('#answer-evidence')){$('#answer-evidence').innerHTML=evidenceMarkup(currentReport,selectedCategory,{language:locale});bindEvidence()}
}
function selectChartTab(key,focus=false){$('#chart-selection').hidden=key!=='map';for(const tab of app.querySelectorAll('[data-chart-tab]')){const active=tab.dataset.chartTab===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$('#panel-'+tab.dataset.chartTab).hidden=!active;if(active&&focus)tab.focus()}updateChartReading()}
function bindChartGallery(){app.querySelectorAll('[data-chart-tab]').forEach(tab=>{tab.onclick=()=>selectChartTab(tab.dataset.chartTab);tab.onkeydown=e=>{const keys=['map','bar','pie','line'],index=keys.indexOf(tab.dataset.chartTab);let next;if(e.key==='ArrowRight')next=(index+1)%keys.length;if(e.key==='ArrowLeft')next=(index+keys.length-1)%keys.length;if(e.key==='Home')next=0;if(e.key==='End')next=keys.length-1;if(next!==undefined){e.preventDefault();selectChartTab(keys[next],true)}}});bindPieControls();bindLineControls()}
function bindGalleryCategories(){app.querySelectorAll('#panel-bar [data-category],#panel-pie [data-category]').forEach(button=>button.onclick=e=>{e.preventDefault();chooseCategory(Number(button.dataset.category))})}
function bindPieControls(){for(const select of app.querySelectorAll('[data-connection-axis]'))select.onchange=()=>{const axis=Number(select.dataset.connectionAxis),value=Number(select.value);pairAxes[axis]=value;if(pairAxes[1-axis]===value)pairAxes[1-axis]=(value+1)%5;pairAxes=normalizePair(pairAxes);chooseCategory(value);app.querySelector(`[data-connection-axis="${axis}"]`)?.focus({preventScroll:true})}}
function bindLineControls(){const select=$('#history-category');if(select)select.onchange=()=>chooseCategory(Number(select.value));app.querySelectorAll('[data-history-point]').forEach(point=>point.onclick=e=>{e.preventDefault();const series=historySeries(db.reports,currentReport,selectedCategory),item=series[Number(point.dataset.historyPoint)];if(item){$('#history-point-detail').textContent=`${dateLabel(item.date)} · ${traits[selectedCategory].name}: ${item.score} / 100`;app.querySelectorAll('[data-history-point]').forEach(other=>other.classList.toggle('active',other.dataset.historyPoint===point.dataset.historyPoint))}})}
function syncGalleryCategory(){if(!$('#bar-chart-content'))return;const historyFocused=document.activeElement?.id==='history-category',pieFocused=document.activeElement?.closest('#panel-pie button[data-category]')?.dataset.category;$('#pie-chart-content').innerHTML=pieChartMarkup(currentReport);$('#line-chart-content').innerHTML=lineChartMarkup(currentReport);bindGalleryCategories();bindPieControls();bindLineControls();if(historyFocused)$('#history-category').focus({preventScroll:true});else if(pieFocused!==undefined)app.querySelector(`#panel-pie button[data-category="${pieFocused}"]`)?.focus({preventScroll:true})}
function updateChartReading(){const key=app.querySelector('[data-chart-tab][aria-selected="true"]')?.dataset.chartTab||'map';if($('#graph-reading'))$('#graph-reading').innerHTML=key==='pie'?connectionReading(currentReport,pairAxes,locale):chartReadingMarkup(key,currentReport,selectedCategory,key==='line'?historySeries(db.reports,currentReport,selectedCategory):[],locale)}
function bindPersonalInsights(){for(const button of app.querySelectorAll('[data-life-context]'))button.onclick=()=>{selectedLifeContext=button.dataset.lifeContext;const story=lifeStory(currentReport.scores,selectedCategory,locale);for(const other of app.querySelectorAll('[data-life-context]'))other.setAttribute('aria-pressed',String(other===button));$('.life-story h4').textContent=button.textContent;$('.life-story p').textContent=story[selectedLifeContext]};for(const button of app.querySelectorAll('[data-reflection]'))button.onclick=()=>{const value=button.dataset.reflection;if(!['fits','depends','different'].includes(value))return;currentReport.reflections=currentReport.reflections&&typeof currentReport.reflections==='object'&&!Array.isArray(currentReport.reflections)?currentReport.reflections:{};currentReport.reflections[selectedCategory]=value;const saved=save();for(const other of app.querySelectorAll('[data-reflection]'))other.setAttribute('aria-pressed',String(other===button));$('#reflection-status').textContent=locale==='hi'?(saved?'आपकी बात इस browser में सेव है। Score नहीं बदला है। आपकी अपनी समझ भी इस रिपोर्ट का हिस्सा है।':'आपकी बात अभी यहाँ है, लेकिन browser में सेव नहीं हो सकी। Score नहीं बदला है।'):(saved?'Your reflection is saved in this browser. Your score stays the same. Your own perspective belongs alongside the numbers.':'Your reflection is here for now, but could not be saved in this browser. Your score stays the same.')}}
function bindEvidence(){for(const button of app.querySelectorAll('[data-response-filter]'))button.onclick=()=>{const key=button.dataset.responseFilter;evidenceFilter=key==='all'?null:Number(key);$('#answer-evidence').innerHTML=evidenceMarkup(currentReport,selectedCategory,{language:locale,filter:evidenceFilter});bindEvidence();const detail=$('#answer-evidence .evidence-answers');if(detail)detail.open=true;app.querySelector(`[data-response-filter="${key}"]`)?.focus({preventScroll:true})}}
function bindCategoryAction(){const button=$('#add-category-action');if(!button)return;button.onclick=()=>{const existing=selectedActions(currentReport).map(a=>a.index);currentReport.categoryPlan=[...new Set([...existing,selectedCategory])];save();button.disabled=true;button.className='secondary';button.textContent=t('Added to your plan ✓');updateCategoryPlan();toast('Added to your plan. Try it whenever you like.')}}
function updateCategoryPlan(){$('#category-plan-content').innerHTML=planMarkup(currentReport);bindCategoryPlan()}
function bindCategoryPlan(){app.querySelectorAll('[data-category-done]').forEach(input=>input.onchange=()=>{const index=Number(input.dataset.categoryDone);currentReport.categoryDone=currentReport.categoryDone||{};currentReport.categoryDone[index]=input.checked;save();const progress=planProgress(currentReport),donut=$('.plan-donut');donut.style.setProperty('--plan-percent',`${progress.percent}%`);donut.setAttribute('aria-label',`${progress.done} of ${progress.total} selected activities tried`);donut.querySelector('strong').innerHTML=`${progress.done}<small> / ${progress.total}</small>`;$('.plan-live').textContent=`${progress.done} of ${progress.total} steps tried.`});app.querySelectorAll('[data-remove-category]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.removeCategory);currentReport.categoryPlan=selectedActions(currentReport).filter(a=>a.index!==index).map(a=>a.index);if(currentReport.categoryDone)delete currentReport.categoryDone[index];save();updateCategoryPlan();if(selectedCategory===index){$('#category-details').innerHTML=categoryDetailMarkup(currentReport);bindCategoryAction();bindPersonalInsights()}})}
function legacyReports(){try{const old=JSON.parse(localStorage.getItem('innerly-v1'));return Array.isArray(old?.reports)?old.reports.filter(r=>['patterns','communication','emotions'].includes(r.test)&&typeof r.id==='string'&&/^\d+$/.test(r.id)&&Array.isArray(r.dims)&&r.dims.length===3&&r.dims.every(s=>Number.isFinite(s)&&s>=0&&s<=100)&&!Number.isNaN(Date.parse(r.date))):[]}catch{return []}}
function history(){setView('history');const legacy=legacyReports();app.innerHTML=`<section class="report-heading"><div class="eyebrow">YOUR PERSONAL SPACE</div><h1>Your saved reports.</h1><p>Saved on this browser. Return whenever you like.</p></section>${db.reports.length?db.reports.map(r=>`<article class="history-card"><div><span class="eyebrow">${r.version===ARCHIVED_VERSION?'45-QUESTION PERSONALITY REFLECTION':'36-QUESTION PERSONALITY REFLECTION'}</span><h2>${r.version===ARCHIVED_VERSION?'Earlier 45-question report':profileFor(r.scores).title}</h2><p>${dateLabel(r.date)}</p></div><button class="secondary" data-report="${escape(r.id)}">View report <span aria-hidden="true">→</span></button></article>`).join(''):`<section class="empty-state"><span aria-hidden="true">♧</span><h2>Your first discovery is waiting.</h2><p>Complete the assessment to see your personality graphs and report here.</p><button class="primary" data-action="${db.draft?'resume':'start'}">${db.draft?'Continue assessment':'Start assessment'} →</button></section>`}${legacy.length?`<section class="legacy-section"><h2>Your earlier reflections</h2><p>These are from the previous short assessments and use a different scoring method.</p>${legacy.map(r=>`<article class="history-card"><div><h3>${({patterns:'Your inner pattern',communication:'Your communication',emotions:'Your emotional world'})[r.test]}</h3><p>${dateLabel(r.date)}</p></div><button class="secondary" data-legacy="${escape(r.id)}">View reflection</button></article>`).join('')}</section>`:''}`;bindActions();app.querySelectorAll('[data-legacy]').forEach(b=>b.onclick=()=>{const r=legacy.find(r=>r.id===b.dataset.legacy),names=({patterns:['Self-awareness','Flexibility','Intentional action'],communication:['Direct expression','Perspective-taking','Healthy boundaries'],emotions:['Emotional awareness','Self-compassion','Regulation']})[r.test];showDialog('Your earlier reflection',`<p>${dateLabel(r.date)} · Previous 12-question exercise</p>${names.map((n,i)=>`<p><strong>${n}:</strong> ${r.dims[i]} / 100</p>`).join('')}<p>This original exercise was not clinically validated. Its scores are not comparable with the new personality assessment.</p><button class="secondary" data-dialog-close>Close reflection</button>`)});focusTitle()}
function shareReport(){if(!currentReport)return;const r=currentReport,p=profileFor(r.scores);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1200"><rect width="1080" height="1200" fill="#f1f5e9"/><text x="80" y="115" fill="#294e3c" font-family="Georgia" font-size="48">✳ innerly.</text><text x="80" y="230" fill="#294e3c" font-family="Georgia" font-size="${Math.min(44,Math.floor(1350/t(p.title).length))}">${escape(t(p.title))}</text><text x="80" y="295" fill="#56684c" font-family="Arial, sans-serif" font-size="25">${locale==='hi'?'मेरी व्यक्तित्व झलक · 36 सवाल':'My personality snapshot · 36-question reflection'}</text>${traits.map((t,i)=>`<text x="80" y="${410+i*125}" fill="#294e3c" font-family="Arial, sans-serif" font-size="29">${t.name}</text><text x="980" y="${410+i*125}" text-anchor="end" fill="#294e3c" font-family="Arial, sans-serif" font-size="29">${r.scores[i]} / 100</text><rect x="80" y="${435+i*125}" width="900" height="14" rx="7" fill="#dce5d0"/><rect x="80" y="${435+i*125}" width="${r.scores[i]*9}" height="14" rx="7" fill="${t.color}"/>`).join('')}<text x="80" y="1100" fill="#56684c" font-family="Arial, sans-serif" font-size="23">${locale==='hi'?'ये पसंद हैं, अंक नहीं। खुद को समझने की शुरुआत।':'Preferences, not grades. A starting point, not a label.'}</text><text x="80" y="1150" fill="#56684c" font-family="Arial, sans-serif" font-size="20">${locale==='hi'?'आत्म-चिंतन अभ्यास · क्लिनिकल सत्यापन नहीं हुआ':'Self-reflection exercise · Not clinically validated'}</text></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='my-innerly-personality.svg';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your summary card is downloaded. Share it only if you want to.')}
function contextMarkup(r){const labels={calm:'Calm self-description',attunement:'Noticing emotions',boundaries:'Making room for your feelings'},items=Array.isArray(r.context)?r.context.filter(item=>labels[item.key]&&Number.isInteger(item.answer)&&item.answer>=0&&item.answer<5):[];if(!items.length)return '';return `<section class="report-panel context-reflections"><h2>Your responses, in context</h2><p class="support-note">These three responses are shown as you selected them. They are not combined into a personality score.</p><div class="context-grid">${items.map(item=>`<article><h3>${labels[item.key]}</h3><p>${escape(questions.find(q=>q.context===item.key).text)}</p><strong>${escape(agreement[item.answer])}</strong></article>`).join('')}</div></section>`}
function archivedReport(r){setView('archived-report');currentReport=r;app.innerHTML=`<section class="report-heading"><h1>Earlier 45-question report</h1><p>${dateLabel(r.date)}</p></section><p class="language-note">This report uses the previous questionnaire. Its scores cannot be compared with the new 36-question report.</p><section class="report-panel">${graphMarkup(r.scores,archivedTraits)}</section><details class="report-panel" open><summary>See all five categories together</summary>${archivedTraits.map((trait,i)=>{const profile=trait.profiles[band(r.scores[i])];return `<article><h2>${trait.name}</h2><h3>${profile.title}</h3><p>${profile.meaning}</p><h4>Your strength</h4><p>${profile.strength}</p><h4>One thing to watch for</h4><p>${profile.watch}</p><h4>Try today</h4><p>${profile.step}</p></article>`}).join('')}</details><div class="report-actions"><button class="secondary" data-action="print">Save full report as PDF ↓</button><button class="secondary" data-action="history">My saved reports</button></div>`;bindActions();focusTitle()}
function showDialog(title,content){$('#info').innerHTML=`<button class="close-dialog" aria-label="Close dialog">×</button><h2 id="dialog-title">${title}</h2>${content}`;$('#info').querySelectorAll('[data-dialog-close],.close-dialog').forEach(b=>b.onclick=()=>$('#info').close());$('#info').showModal()}
function about(){showDialog('A mirror, not a label.',`<p>Innerly is a name inspired by your inner world: your thoughts, feelings, and preferences.</p><p>This is an unvalidated self-reflection questionnaire based on the supplied statements. It does not diagnose a condition or measure your worth, abilities, or suitability.</p><p>Assessment answers, unfinished progress, reports, language, motion and text-size preferences are stored in this browser. No account is needed. There is no server collection of your responses. Downloading a card does not post it anywhere. The optional email draft opens your own email app; you decide whether to send it.</p><p>Your short summary and full report are free for now. No payment details are collected.</p><button class="secondary" id="clear-data">Clear my saved data</button>`);$('#clear-data').onclick=()=>{showDialog('Clear data on this device?',`<p>This removes your unfinished answers, completed reports, and earlier reflections from this browser. Download any report you want to keep first.</p><div class="dialog-actions"><button class="secondary" data-dialog-close>Keep my data</button><button class="danger" id="confirm-clear">Clear my data</button></div>`);$('#confirm-clear').onclick=()=>{try{localStorage.removeItem(storageKey);localStorage.removeItem('innerly-v1');db={reports:[],draft:null,large:db.large};save();$('#info').close();currentReport=null;home();toast('Your saved answers and reports have been cleared.')}catch{toast('This browser could not clear saved data. Please use your browser’s storage settings.')}}}}
function goHome(){if(view==='quiz')persistDraft();home()}
$('#home-nav').onclick=goHome;$('.brand').onclick=e=>{e.preventDefault();goHome()};$('#reports-nav').onclick=()=>{if(view==='quiz')persistDraft();history()};$('#regular-type').onclick=()=>setText(false);$('#large-type').onclick=()=>setText(true);$('#about').onclick=$('#privacy').onclick=about;$('#info').addEventListener('click',e=>{if(e.target===$('#info'))$('#info').close()});document.addEventListener('keydown',e=>{if(view!=='quiz'||$('#info').open||e.ctrlKey||e.metaKey||e.altKey||e.repeat||!/^Digit[1-5]$/.test(e.code))return;const card=document.activeElement?.closest('[data-question-index]');if(!card)return;e.preventDefault();const questionIndex=Number(card.dataset.questionIndex),value=Number(e.code.slice(-1))-1;selectAnswer(value,questionIndex);card.querySelector(`input[value="${value}"]`).focus({preventScroll:true})});window.addEventListener('beforeunload',e=>{if(view==='quiz'&&hasUnsavedAnswers){e.preventDefault();e.returnValue=''}});setText(db.large,false);home(false);
const translatePage=installPageTranslation();
const languageControl=$('#language');
languageControl.innerHTML=languages.map(item=>`<option value="${item.code}">${item.name}</option>`).join('');languageControl.value=locale;
languageControl.onchange=()=>{if(view==='quiz')persistDraft();const chosen=languageControl.value;if(['home','quiz'].includes(view)){assessmentLanguage=chosen;try{localStorage.setItem('innerly-language',chosen)}catch{}}useLanguage(chosen);const url=new URL(location.href);url.searchParams.set('lang',assessmentLanguage);window.history.replaceState(null,'',url);if($('#info').open)$('#info').close();if(view==='quiz')quiz();else if(view==='home')home(false);else if(view==='result'){const category=selectedCategory,chart=app.querySelector('[data-chart-tab][aria-selected="true"]')?.dataset.chartTab;result(currentReport,false);if(currentReport.fullViewed){chooseCategory(category);if(chart)selectChartTab(chart)}}else if(view==='archived-report')archivedReport(currentReport);else if(view==='history')history();else if(view==='save-report')saveReportScreen(currentReport);else if(view==='report-preview')reportPreview(currentReport);translatePage();};


let closedPrintDetails=[],hiddenPrintPanels=[];
window.addEventListener('beforeprint',()=>{hiddenPrintPanels=[...document.querySelectorAll('.chart-gallery [role=tabpanel][hidden]')];hiddenPrintPanels.forEach(panel=>{panel.hidden=false});closedPrintDetails=[...document.querySelectorAll('#full-report details:not([open])')];closedPrintDetails.forEach(detail=>{detail.open=true})});
window.addEventListener('afterprint',()=>{hiddenPrintPanels.forEach(panel=>{if(panel.isConnected)panel.hidden=true});hiddenPrintPanels=[];closedPrintDetails.forEach(detail=>{if(detail.isConnected)detail.open=false});closedPrintDetails=[]});
